data class PersonRow(val id: Long, var lastName: String, var deps: Int)

fun PersonRow.update(conn: Connection) =
    conn.prepareStatement("UPDATE people SET last_name=?, deps=? WHERE id=?").use { ps ->
        ps.setString(1, lastName); ps.setInt(2, deps); ps.setLong(3, id); ps.executeUpdate()
    }
fun findPerson(conn: Connection, id: Long): PersonRow? =
    conn.prepareStatement("SELECT id, last_name, deps FROM people WHERE id=?").use { ps ->
        ps.setLong(1, id)
        ps.executeQuery().use { rs -> if (rs.next()) PersonRow(rs.getLong(1), rs.getString(2), rs.getInt(3)) else null }
    }

