object People : LongIdTable("people") {
    val lastName = varchar("last_name", 64)
    val deps = integer("deps")
}

class PersonEntity(id: EntityID<Long>) : LongEntity(id) {
    companion object : LongEntityClass<PersonEntity>(People)
    var lastName by People.lastName
    var deps by People.deps
}

